package com.bank.audit.model;

import jakarta.persistence.*;
import org.hibernate.envers.Audited;        // Envers history
import org.springframework.data.annotation.*;  // Spring Data auditing
import org.springframework.data.jpa.domain.support.AuditingEntityListener;
import java.math.BigDecimal;
import java.time.Instant;

@Entity
@Table(name = "accounts")
@Audited                                        // Envers keeps full history
@EntityListeners(AuditingEntityListener.class)  // Spring Data stamps current row
public class Account {
    @Id private String id;
    @Column(name = "holder_name") private String holderName;
    private BigDecimal balance;

    @CreatedDate   @Column(name = "created_at", updatable = false) private Instant createdAt;
    @LastModifiedDate @Column(name = "updated_at") private Instant updatedAt;
    @CreatedBy     @Column(name = "created_by", updatable = false) private String createdBy;
    @LastModifiedBy @Column(name = "updated_by") private String updatedBy;

    protected Account() {}
    public Account(String id, String holderName, BigDecimal balance) {
            this.id = id;
            this.holderName = holderName
            this.balance = balance;
    }
    public String getId() { return id; }
    public BigDecimal getBalance() { return balance; }
    public void setBalance(BigDecimal b) { this.balance = b; }
    public Instant getUpdatedAt() { return updatedAt; }
}
