package com.bank.audit.service;

import com.bank.audit.model.Account;
import jakarta.persistence.*;
import lombok.extern.slf4j.Slf4j;
import org.hibernate.envers.AuditReader;
import org.hibernate.envers.AuditReaderFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Slf4j
@Service
public class HistoryService {

    @PersistenceContext
    private EntityManager em;

    // Read every revision number for an account (Envers)
    @Transactional(readOnly = true)
    public List<Number> revisionsOf(String accountId) {
        AuditReader reader = AuditReaderFactory.get(em);
        return reader.getRevisions(Account.class, accountId);
    }

    // Reconstruct the account as it looked at a given revision (Envers)
    @Transactional(readOnly = true)
    public Account accountAtRevision(String accountId, Number revision) {
        AuditReader reader = AuditReaderFactory.get(em);
        Account past = reader.find(Account.class, accountId, revision);
        log.info("Account {} at revision {} had balance {}",
                 accountId, revision, past.getBalance());
        return past;
    }
}
